-- Every 2023 payment drug and device makers gave to US doctors and hospitals -- 14.7 million records.
-- Auto-generated by scripts/gen_evidence_pages.py: 14,700,786 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("DATE_OF_PAYMENT") as year, count(*) as records
from THE_LIBRARY.HEALTH.PHARMA_PAYMENTS_TO_DOCTORS_2023
where "DATE_OF_PAYMENT" is not null
group by 1
order by 1
